'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { RateLimiter } = require('../index.js');

test('remaining resets exactly at the window edge', () => {
  const rl = new RateLimiter({ limit: 2, windowMs: 1000 });
  rl.allow('a', 0);
  assert.strictEqual(rl.remaining('a', 999), 1);
  assert.strictEqual(rl.remaining('a', 1000), 2);
});
